Context("LimitedFraction")->flags->set(allowMixedNumbers => 0, showMixedNumbers => 0); $range = [2..20]; do { ($a,$b,$c) = num_sort(random_pairwise_coprime($range, $range, $range)); } until (gcd($b - $a, $c) > 1); $A = Fraction($a,$c); $B = Fraction($b,$c); $ans = $B - $A;
